<parameter name="command">cd /tmp/auth-demo && npm install express sqlite3 bcrypt express-session express-rate-limit</parameter>
</invoke>
</function_calls>

Now creating the core files:
<function_calls>
<invoke name="write">
<parameter name="path">/tmp/auth-demo/db.js</parameter>
<parameter name="content">const sqlite3 = require('sqlite3').verbose();
const path = require('path');

const db = new sqlite3.Database(path.join(__dirname, 'auth.db'));

db.serialize(() => {
  db.run(`
    CREATE TABLE IF NOT EXISTS users (
      id INTEGER PRIMARY KEY AUTOINCREMENT,
      email TEXT UNIQUE NOT NULL,
      password_hash TEXT NOT NULL,
      created_at DATETIME DEFAULT CURRENT_TIMESTAMP
    )
  `);
});

module.exports = db;
</parameter>
</invoke>
</function_calls>
<function_calls>
<invoke name="write">
<parameter name="path">/tmp/auth-demo/auth.js</parameter>
<parameter name="content">const bcrypt = require('bcrypt');
const db = require('./db');

async function hashPassword(password) {
  return bcrypt.hash(password, 10);
}

async function verifyPassword(password, hash) {
  return bcrypt.compare(password, hash);
}

function createUser(email, passwordHash) {
  return new Promise((resolve, reject) => {
    db.run(
      'INSERT INTO users (email, password_hash) VALUES (?, ?)',
      [email, passwordHash],
      function(err) {
        if (err) reject(err);
        else resolve({ id: this.lastID, email });
      }
    );
  });
}

function getUserByEmail(email) {
  return new Promise((resolve, reject) => {
    db.get(
      'SELECT * FROM users WHERE email = ?',
      [email],
      (err, row) => {
        if (err) reject(err);
        else resolve(row);
      }
    );
  });
}

module.exports = {
  hashPassword,
  verifyPassword,
  createUser,
  getUserByEmail
};
</parameter>
</invoke>
</function_calls>
<function_calls>
<invoke name="write">
<parameter name="path">/tmp/auth-demo/server.js</parameter>
<parameter name="content">const express = require('express');
const session = require('express-session');
const rateLimit = require('express-rate-limit');
const { hashPassword, verifyPassword, createUser, getUserByEmail } = require('./auth');

const app = express();
app.use(express.json());

const failedAttempts = new Map();

app.use(session({
  secret: 'your-secret-key-change-in-production',
  resave: false,
  saveUninitialized: false,
  cookie: { 
    secure: false,
    httpOnly: true,
    maxAge: 24 * 60 * 60 * 1000
  }
}));

const loginLimiter = rateLimit({
  windowMs: 15 * 60 * 1000,
  max: 5,
  keyGenerator: (req) => req.body.email || req.ip,
  skip: (req) => req.session.userId,
  message: 'Too many failed login attempts. Try again in 15 minutes.'
});

app.post('/signup', async (req, res) => {
  const { email, password } = req.body;

  if (!email || !password) {
    return res.status(400).json({ error: 'Email and password required' });
  }

  if (password.length < 8) {
    return res.status(400).json({ error: 'Password must be 8+ chars' });
  }

  try {
    const existing = await getUserByEmail(email);
    if (existing) {
      return res.status(409).json({ error: 'Email already registered' });
    }

    const hash = await hashPassword(password);
    const user = await createUser(email, hash);

    req.session.userId = user.id;
    req.session.email = user.email;

    res.status(201).json({ message: 'Signup successful', user });
  } catch (err) {
    res.status(500).json({ error: 'Signup failed' });
  }
});

app.post('/login', loginLimiter, async (req, res) => {
  const { email, password } = req.body;

  if (!email || !password) {
    return res.status(400).json({ error: 'Email and password required' });
  }

  try {
    const user = await getUserByEmail(email);

    if (!user) {
      failedAttempts.set(email, (failedAttempts.get(email) || 0) + 1);
      return res.status(401).json({ error: 'Invalid email or password' });
    }

    const valid = await verifyPassword(password, user.password_hash);

    if (!valid) {
      failedAttempts.set(email, (failedAttempts.get(email) || 0) + 1);
      return res.status(401).json({ error: 'Invalid email or password' });
    }

    failedAttempts.delete(email);
    req.session.userId = user.id;
    req.session.email = user.email;

    res.json({ message: 'Login successful', user: { id: user.id, email: user.email } });
  } catch (err) {
    res.status(500).json({ error: 'Login failed' });
  }
});

app.post('/logout', (req, res) => {
  req.session.destroy((err) => {
    if (err) return res.status(500).json({ error: 'Logout failed' });
    res.json({ message: 'Logged out' });
  });
});

app.get('/protected', (req, res) => {
  if (!req.session.userId) {
    return res.status(401).json({ error: 'Unauthorized' });
  }
  res.json({ message: 'Protected data', user: req.session.email });
});

app.listen(3000, () => {
  console.log('Server on http://localhost:3000');
});
